import type { OfferItem } from "@game/shared";
import iconFrames from "./iconFrames.json";

/**
 * Which icon of the shared `items` sheet stands for what (pure data; the DOM
 * components are in icons.ts). `iconFrames.json` is generated by `pnpm art`.
 */
export type IconName = keyof typeof iconFrames.icons;

export interface IconFrame {
  x: number;
  y: number;
  frames: number;
}

/** Size of `items.png` and the first-frame rect of every icon. */
export const ICON_SHEET: { w: number; h: number; icons: Record<IconName, IconFrame> } = iconFrames;

export const isIconName = (v: unknown): v is IconName => typeof v === "string" && Object.hasOwn(iconFrames.icons, v);

/** Every relic, weapon and shop item has an icon of the same name. */
export const ITEM_ICON: Readonly<Record<OfferItem, IconName>> = {
  heart: "heart",
  power: "power",
  boots: "boots",
  clover: "clover",
  eye: "eye",
  mark: "mark",
  fang: "fang",
  shield: "shield",
  haste: "haste",
  dagger: "dagger",
  fireball: "fireball",
  arrow: "arrow",
  nova: "nova",
  potion: "potion",
};

/** Rows of the attribute lists (hero-select cards, details panel). */
export type StatRow =
  | "hp"
  | "damage"
  | "speed"
  | "attackSpeed"
  | "cooldown"
  | "defense"
  | "critChance"
  | "critDamage"
  | "lifesteal"
  | "luck";

/** Attribute → the icon of the relic that improves it (attack speed: the sword). */
export const STAT_ICON: Readonly<Record<StatRow, IconName>> = {
  hp: "heart",
  damage: "power",
  speed: "boots",
  attackSpeed: "sword",
  cooldown: "haste",
  defense: "shield",
  critChance: "eye",
  critDamage: "mark",
  lifesteal: "fang",
  luck: "clover",
};

/** Rows of the end-of-match summary (`summary.<row>` keys); time has no icon. */
export type SummaryRow = "kills" | "monsters" | "bosses" | "chests" | "level" | "relics" | "time";

export const SUMMARY_ICON: Readonly<Record<SummaryRow, IconName | undefined>> = {
  kills: "sword",
  monsters: "sum-monsters",
  bosses: "mark-boss",
  chests: "chest",
  level: "sum-level",
  relics: "sum-relics",
  time: undefined,
};

/** HUD heart fill in quarters (0 = empty, only when down; 1..4 otherwise). */
export const heartQuarter = (hp: number, max: number) =>
  hp <= 0 ? 0 : Math.min(4, Math.max(1, Math.ceil((4 * hp) / Math.max(1, max))));

/** HUD heart icon for a quarter: `hp-0` … `hp-4`. */
export const heartIcon = (quarter: number): IconName =>
  `hp-${Math.min(4, Math.max(0, Math.round(quarter)))}` as IconName;

/** Rows (0..16) of a weapon slot shaded while it recharges: `cd` ticks left of `maxCd`. */
export const cooldownRows = (cd: number, maxCd: number) =>
  Math.min(16, Math.max(0, Math.ceil((16 * cd) / Math.max(1, maxCd))));
